INSERT INTO `articles` (`id`, `user_id`, `title`, `abstract`, `views`, `visited`, `created`) VALUES
(1, 1, 'Introduction', 'How to get rid of all of your stuff and live in a box with wheels for a year.', 198, '2011-01-01 00:00:00', '2011-02-06 21:33:20'),
(2, 1, 'Getting Started By Being Able To Stop', 'A week in Fremont at Applied GMC where we totally redid the whole braking system.', 147, '2011-01-10 00:00:00', '2011-02-13 20:32:57'),
(3, 1, 'Bulldozer Office Building', 'Bringing new meaning to the term pencil pusher', 132, '2011-01-16 00:00:00', '2011-02-19 21:35:46'),
(4, 1, 'Vasquez Rocks', 'Where space folk go to work out their differences', 141, '2011-01-18 00:00:00', '2011-02-19 21:39:35'),
(5, 1, 'Castle Air Museum', 'Step one in our quest to see as many airplanes on this trip as possible', 88, '2011-01-16 01:00:00', '2011-03-08 19:58:33'),
(6, 1, 'Salvation Mountain', 'A folk art masterpiece made from the least likely materials.', 120, '2011-01-22 00:00:00', '2011-03-08 20:05:59'),
(7, 1, 'Official Center of the World	', 'A library for the aliens or future civilizations to figure out what the hell we were doing.', 229, '2011-01-22 01:00:00', '2011-03-08 20:14:09'),
