(43, 2, 'Southern Weather', 'A Californian&#8217;s first encounter with a tornado', 208, '2011-04-26 00:00:00', '2011-06-07 14:28:37'),
(45, 2, 'Regional Junk Foods of the South', 'Not a vegetable in sight, unless you count the potato chips.', 251, '2011-03-14 00:00:00', '2011-06-27 21:41:20'),
(46, 2, 'Wormsloe Plantation', 'The king of oak lined avenues.', 338, '2011-04-05 00:00:00', '2011-07-01 22:11:30'),
