(51, 2, '5', 'Air Force junior', 'Training for the kiddies!', 'http://50states.s3.amazonaws.com/51_2_1024.jpg', 'http://50states.s3.amazonaws.com/51_2_200c.jpg', '', '1024', '1001', 1, 33, '2011-03-14 19:59:45'),
(52, 2, '5', 'GRR', 'shark plane!', 'http://50states.s3.amazonaws.com/52_2_1024.jpg', 'http://50states.s3.amazonaws.com/52_2_200c.jpg', '', '1024', '1001', 1, 38, '2011-03-14 20:02:34'),
(53, 2, '12', 'Salton Sea Cacti', 'See, not everything is dead at the Salton Sea!', 'http://50states.s3.amazonaws.com/53_2_1024.jpg', 'http://50states.s3.amazonaws.com/53_2_200c.jpg', '', '1024', '1001', 1, 40, '2011-03-14 20:05:51'),
(54, 2, '16', 'Shields Date Garden', 'Home of the Date Shake.', 'http://50states.s3.amazonaws.com/54_2_1024.jpg', 'http://50states.s3.amazonaws.com/54_2_200c.jpg', '', '1024', '1001', 1, 41, '2011-03-14 20:07:49'),
(55, 2, '6', 'Salvation Mountain', 'The place of endless photo opportunities. ', 'http://50states.s3.amazonaws.com/55_2_1024.jpg', 'http://50states.s3.amazonaws.com/55_2_200c.jpg', '', '1024', '1001', 1, 38, '2011-03-14 20:11:50'),
(56, 2, '7', 'The chapel at the center of the world', 'The french style chapel at the Center of the World, in Felicity California.', 'http://50states.s3.amazonaws.com/56_2_1024.jpg', 'http://50states.s3.amazonaws.com/56_2_200c.jpg', '', '1024', '1001', 1, 45, '2011-03-14 20:18:09'),
(57, 2, '7', 'PLUTO!', 'For all of you that will always consider Pluto a proper planet, you''ll be happy to know when the aliens land and learn about our Earth ways from the stone tablets in Felicity, they will too.', 'http://50states.s3.amazonaws.com/57_2_1024.jpg', 'http://50states.s3.amazonaws.com/57_2_200c.jpg', '', '1024', '1001', 1, 29, '2011-03-14 20:23:18'),
(58, 2, '10', 'warning', 'Caution, watch for exploding children?', 'http://50states.s3.amazonaws.com/58_2_1024.jpg', 'http://50states.s3.amazonaws.com/58_2_200c.jpg', '', '1024', '1001', 1, 51, '2011-03-14 20:26:46'),
(59, 2, '10', 'atomic cannon', 'Seems like an excellent idea.', 'http://50states.s3.amazonaws.com/59_2_1024.jpg', 'http://50states.s3.amazonaws.com/59_2_200c.jpg', '', '1024', '1001', 1, 71, '2011-03-14 20:33:46'),
(60, 2, '21', 'Bridge to nowhere', 'Good for photos, not so much for driving.', 'http://50states.s3.amazonaws.com/60_2_1024.jpg', 'http://50states.s3.amazonaws.com/60_2_200c.jpg', '', '1024', '1001', 1, 43, '2011-03-14 20:41:37'),
(61, 2, '42', 'Yuma Territorial Prison', 'Once a prison, then a high school (actual mascot, the "crims") then the star of 2 excellent westerns.', 'http://50states.s3.amazonaws.com/61_2_1024.jpg', 'http://50states.s3.amazonaws.com/61_2_200c.jpg', '', '1024', '1001', 1, 32, '2011-03-14 20:45:29'),
(62, 2, '42', 'yuma prison cells', 'They are pretty tiny, but at least they had airflow. Yuma is really hot.', 'http://50states.s3.amazonaws.com/62_2_1024.jpg', 'http://50states.s3.amazonaws.com/62_2_200c.jpg', '', '1024', '1001', 1, 44, '2011-03-14 20:49:09'),
(63, 2, '44', 'san xavier del bac mission', 'So glad this time there''s no scaffolding!', 'http://50states.s3.amazonaws.com/63_2_1024.jpg', 'http://50states.s3.amazonaws.com/63_2_200c.jpg', '', '1024', '1001', 1, 44, '2011-03-14 20:53:35'),
(64, 2, '44', 'san xavier tower', 'Insane spanish mission just south of Tucson.', 'http://50states.s3.amazonaws.com/64_2_1024.jpg', 'http://50states.s3.amazonaws.com/64_2_200c.jpg', '', '1024', '1001', 1, 48, '2011-03-14 20:56:59'),
