(140, 1, '17', 'Knobs', 'The very bumpy landscape of Chiricahua National Monument.', 'http://50states.s3.amazonaws.com/140_1_1024.jpg', 'http://50states.s3.amazonaws.com/140_1_200c.jpg', '', '1024', '683', 1, 28, '2011-03-20 20:23:51'),
(141, 1, '47', 'Teepee Cafe', 'A sadly derelict teepee shaped cafe in the also sadly derelict seeming Bowie AZ.', 'http://50states.s3.amazonaws.com/141_1_1024.jpg', 'http://50states.s3.amazonaws.com/141_1_200c.jpg', '', '1024', '683', 1, 40, '2011-03-20 20:27:15'),
(143, 1, '47', 'Teepee Cafe', 'No longer a cafe, but the building is for sale...', 'http://50states.s3.amazonaws.com/143_1_1024.jpg', 'http://50states.s3.amazonaws.com/143_1_200c.jpg', '', '1024', '683', 1, 46, '2011-03-20 20:28:58'),
(144, 1, '24', 'Main Entrance', 'The staircase leading up into the Cliff Dwellings.', 'http://50states.s3.amazonaws.com/144_1_1024.jpg', 'http://50states.s3.amazonaws.com/144_1_200c.jpg', 'http://50states.s3.amazonaws.com/144_1_600.jpg', '1024', '683', 1, 54, '2011-03-20 20:31:22'),
(145, 1, '24', 'Opening #2', 'The second opening into the cliff face. This part was not accessible from the outside.', 'http://50states.s3.amazonaws.com/145_1_1024.jpg', 'http://50states.s3.amazonaws.com/145_1_200c.jpg', '', '1024', '683', 1, 44, '2011-03-20 20:33:19'),
(146, 1, '24', 'Across the Valley', 'From the other side of the valley, showing  the cliff face.', 'http://50states.s3.amazonaws.com/146_1_1024.jpg', 'http://50states.s3.amazonaws.com/146_1_200c.jpg', '', '1024', '683', 1, 38, '2011-03-20 20:35:34'),
(147, 1, '24', 'Across the dwellings', 'Looking back over the dwellings towards the trail we came up on.', 'http://50states.s3.amazonaws.com/147_1_1024.jpg', 'http://50states.s3.amazonaws.com/147_1_200c.jpg', '', '1024', '683', 1, 40, '2011-03-20 20:37:12'),
(148, 1, '24', 'Double Arch', 'A building built into the space between two openings in the cliff. It is one giant cave with 3 or 4 openings.', 'http://50states.s3.amazonaws.com/148_1_1024.jpg', 'http://50states.s3.amazonaws.com/148_1_200c.jpg', '', '1024', '683', 1, 49, '2011-03-20 20:38:50'),
(149, 1, '24', 'The Main Chamber', 'This is the big chamber by the entrance. the ceiling is totally black from soot.', 'http://50states.s3.amazonaws.com/149_1_1024.jpg', 'http://50states.s3.amazonaws.com/149_1_200c.jpg', '', '1024', '683', 1, 41, '2011-03-20 20:40:06'),
(150, 1, '24', 'Exit from the Dwelllings', 'Alana, sitting on the stairs down to the ladder that takes you out.', 'http://50states.s3.amazonaws.com/150_1_1024.jpg', 'http://50states.s3.amazonaws.com/150_1_200c.jpg', '', '1024', '683', 1, 41, '2011-03-20 20:46:58'),
(151, 1, '24', 'Inside the Main Chamber', 'Just inside the entrance looking deep into the dwellings.', 'http://50states.s3.amazonaws.com/151_1_1024.jpg', 'http://50states.s3.amazonaws.com/151_1_200c.jpg', '', '1024', '683', 1, 47, '2011-03-20 20:50:39'),
(152, 1, '20', 'Tom Mix... Gunslinger!', 'A studio portrait of Tom Mix, the King of the Cowboys.', 'http://50states.s3.amazonaws.com/152_1_1024.jpg', 'http://50states.s3.amazonaws.com/152_1_200c.jpg', '', '1024', '758', 1, 47, '2011-03-30 22:24:05'),
(153, 1, '52', 'Rudy''s BBQ', 'Overall the best bbq experience we had in Texas. The chicken was superb and the beans were great. The location was the best part though, it is housed in gas station.', 'http://50states.s3.amazonaws.com/153_1_1024.jpg', 'http://50states.s3.amazonaws.com/153_1_200c.jpg', 'http://50states.s3.amazonaws.com/153_1_600.jpg', '1024', '768', 1, 72, '2011-03-31 09:44:22'),
(154, 1, '62', 'El Charro Cafe', 'Owned by the same family since the 20s, this place is a Tucson institution. A little touristy, but good.', 'http://50states.s3.amazonaws.com/154_1_1024.jpg', 'http://50states.s3.amazonaws.com/154_1_200c.jpg', 'http://50states.s3.amazonaws.com/154_1_600.jpg', '1024', '683', 1, 39, '2011-03-31 10:24:45'),
(155, 2, '56', 'Saturn 5', 'Detail of the Saturn 5 rocket at Johnson Space Center in Houston, TX.', 'http://50states.s3.amazonaws.com/155_2_1024.jpg', 'http://50states.s3.amazonaws.com/155_2_200c.jpg', '', '1024', '1001', 1, 41, '2011-03-31 15:32:52'),
(156, 2, '56', 'V', 'This building at Johnson Space Center has a Saturn 5 rocket made from the scrapped Apollo missions.', 'http://50states.s3.amazonaws.com/156_2_1024.jpg', 'http://50states.s3.amazonaws.com/156_2_200c.jpg', '', '1024', '1001', 1, 31, '2011-03-31 15:44:24'),
(157, 2, '63', 'Window View', 'From the master bedroom at Rosedown Plantation in St Francisville Louisiana.', 'http://50states.s3.amazonaws.com/157_2_1024.jpg', 'http://50states.s3.amazonaws.com/157_2_200c.jpg', '', '1024', '1001', 1, 37, '2011-03-31 15:50:33'),
(158, 2, '63', 'Wallpaper', 'Rosedown Plantation has what looks like a super colorful mural of fairy tales (?) in the entryway, but it''s actually 1 foot square canvas handpainted wallpaper tiles from the early 1800''s. ', 'http://50states.s3.amazonaws.com/158_2_1024.jpg', 'http://50states.s3.amazonaws.com/158_2_200c.jpg', '', '1024', '1365', 1, 19, '2011-03-31 16:07:46'),
(159, 2, '63', 'Miss Turnbull', 'The Belle of the county and the heiress to Rosedown Plantation. She married the guy next door and had 8 kids, who kept the house in the family until the 1950''s.', 'http://50states.s3.amazonaws.com/159_2_1024.jpg', 'http://50states.s3.amazonaws.com/159_2_200c.jpg', '', '1024', '1365', 1, 28, '2011-03-31 16:14:49'),
(160, 2, '63', 'Curtain Arms', 'The Turnbull''s had a lot of their furniture custom made for Rosedown, which was common in the 1840''s. They also had these curtain tie back''s made from Martha''s specifications.', 'http://50states.s3.amazonaws.com/160_2_1024.jpg', 'http://50states.s3.amazonaws.com/160_2_200c.jpg', '', '1024', '1365', 1, 40, '2011-03-31 16:21:56'),
(161, 2, '63', 'Rosedown Plantation', 'It''s not really my favorite style of architecture, but you really can''t argue with all that porch. Perfect for sitting in a rocking chair and drinking mint juleps.', 'http://50states.s3.amazonaws.com/161_2_1024.jpg', 'http://50states.s3.amazonaws.com/161_2_200c.jpg', '', '1024', '768', 1, 30, '2011-03-31 16:26:49'),
(162, 2, '65', 'French Quarter Cat', 'For some reason I took hardly any photos (in between stuffing my face) in New Orleans, but I did get a shot of this cute cat.', 'http://50states.s3.amazonaws.com/162_2_1024.jpg', 'http://50states.s3.amazonaws.com/162_2_200c.jpg', '', '1024', '1001', 1, 49, '2011-03-31 16:30:31'),
(163, 2, '64', 'At least they recycle something', 'Outside of California there is no such thing as recycling. Unless you are at a Whole Foods, and it''s the week after Mardi Gras.', 'http://50states.s3.amazonaws.com/163_2_1024.jpg', 'http://50states.s3.amazonaws.com/163_2_200c.jpg', '', '1024', '1001', 1, 45, '2011-03-31 16:44:50'),
(164, 2, '66', 'LM', 'At a rest area in Mississippi, we spotted what turned out to be the Lunar Module trainer for Apollo 13.', 'http://50states.s3.amazonaws.com/164_2_1024.jpg', 'http://50states.s3.amazonaws.com/164_2_200c.jpg', '', '1024', '1001', 1, 36, '2011-03-31 16:51:47'),
(165, 2, '67', 'Gator Farm', 'I kept my arms well inside the fence. The gators looked pretty lazy, but then so did our killer cat.', 'http://50states.s3.amazonaws.com/165_2_1024.jpg', 'http://50states.s3.amazonaws.com/165_2_200c.jpg', '', '1024', '1001', 1, 41, '2011-03-31 16:59:48'),
(166, 2, '67', 'Gator Fence', 'At the Gator Farm on the Mississippi Alabama border.', 'http://50states.s3.amazonaws.com/166_2_1024.jpg', 'http://50states.s3.amazonaws.com/166_2_200c.jpg', '', '1024', '1001', 1, 54, '2011-03-31 17:37:06'),
(167, 2, '68', 'Pensacola Beach', 'Hard to argue with.', 'http://50states.s3.amazonaws.com/167_2_1024.jpg', 'http://50states.s3.amazonaws.com/167_2_200c.jpg', '', '1024', '1001', 1, 52, '2011-03-31 17:44:22'),
(168, 2, '68', 'Pensacola Beach Fishing', 'We only got to stay one night in Pensacola, and we were sad.', 'http://50states.s3.amazonaws.com/168_2_1024.jpg', 'http://50states.s3.amazonaws.com/168_2_200c.jpg', '', '1024', '768', 1, 47, '2011-03-31 17:47:26'),
(169, 2, '69', 'Jai-Alai', 'Definitely one of the strangest things we''ve stumbled upon so far is this abandoned Jai- Alai stadium in the middle of nowhere in Florida. ', 'http://50states.s3.amazonaws.com/169_2_1024.jpg', 'http://50states.s3.amazonaws.com/169_2_200c.jpg', '', '1024', '1001', 1, 173, '2011-03-31 17:54:31'),
(170, 2, '34', 'Ocean Pond', 'At Osceola National Forest outside Lake City Florida.', 'http://50states.s3.amazonaws.com/170_2_1024.jpg', 'http://50states.s3.amazonaws.com/170_2_200c.jpg', '', '1024', '1365', 1, 77, '2011-03-31 17:58:16'),
(171, 2, '34', 'Road to Ocean Pond', 'Florida has the strangest forests. In Northern Florida it''s tall skinny pine trees, with a 4 foot high carpet of palms. Odd combination.', 'http://50states.s3.amazonaws.com/171_2_1024.jpg', 'http://50states.s3.amazonaws.com/171_2_200c.jpg', '', '1024', '768', 1, 41, '2011-03-31 18:01:03'),
(172, 2, '34', 'Lakeside', 'At Ocean Pond Campground. No gators, just mosquitos and Kenny Powers lookalikes. Still a pretty view though.', 'http://50states.s3.amazonaws.com/172_2_1024.jpg', 'http://50states.s3.amazonaws.com/172_2_200c.jpg', '', '1024', '768', 1, 58, '2011-03-31 18:08:33'),
(173, 2, '34', 'The Campground at Ocean Pond', 'Super pretty, and we stayed 4 nights for $36. ', 'http://50states.s3.amazonaws.com/173_2_1024.jpg', 'http://50states.s3.amazonaws.com/173_2_200c.jpg', '', '1024', '768', 1, 80, '2011-03-31 18:15:45'),
(174, 2, '40', 'Haunted Mansion', 'At Disney World in Orlando. Definitely my favorite ride, even though it broke down twice. ', 'http://50states.s3.amazonaws.com/174_2_1024.jpg', 'http://50states.s3.amazonaws.com/174_2_200c.jpg', '', '1024', '1365', 1, 52, '2011-03-31 18:20:21'),
(175, 2, '40', 'Jungle Cruise', 'At Disney World in Florida. Kind of a silly ride, but our tour guide sure was working hard to make it funny. The kid in the foreground was terrified of everything on it.', 'http://50states.s3.amazonaws.com/175_2_1024.jpg', 'http://50states.s3.amazonaws.com/175_2_200c.jpg', '', '1024', '768', 1, 55, '2011-03-31 18:24:29'),
(176, 2, '40', 'Post Parade Crowd', 'It wasn''t as crowded as I thought it was going to be, for a friday on spring break, but it sure was crowded for a few minutes in Frontierland after the parade ended.', 'http://50states.s3.amazonaws.com/176_2_1024.jpg', 'http://50states.s3.amazonaws.com/176_2_200c.jpg', '', '1024', '768', 1, 50, '2011-03-31 18:27:10'),
(177, 2, '40', 'Tram Safety', 'Please do not ghost ride with your short friend on the tram.', 'http://50states.s3.amazonaws.com/177_2_1024.jpg', 'http://50states.s3.amazonaws.com/177_2_200c.jpg', '', '1024', '768', 1, 53, '2011-03-31 18:29:34'),
(178, 2, '40', 'Proof!', 'Finally a photo of one of us, and proof that we actually went on this trip, and aren''t just making it up from an apartment somewhere.', 'http://50states.s3.amazonaws.com/178_2_1024.jpg', 'http://50states.s3.amazonaws.com/178_2_200c.jpg', '', '1024', '768', 1, 82, '2011-03-31 18:34:51'),
(179, 2, '40', 'Outside the Jungle Cruise', 'These were between the Jungle Cruise and the Swiss Family Robinson Treehouse, which was Paul''s favorite as a kid. ', 'http://50states.s3.amazonaws.com/179_2_1024.jpg', 'http://50states.s3.amazonaws.com/179_2_200c.jpg', '', '1024', '768', 1, 51, '2011-03-31 19:02:42'),
(180, 2, '70', 'Epcot', 'Epcot is a very odd park. You can see this from the Morocco pavilion.', 'http://50states.s3.amazonaws.com/180_2_1024.jpg', 'http://50states.s3.amazonaws.com/180_2_200c.jpg', '', '1024', '1001', 1, 54, '2011-03-31 20:05:53'),
(181, 2, '70', 'The Beast and Belle', 'Visit France, or at least the Disney abbreviated version of France.', 'http://50states.s3.amazonaws.com/181_2_1024.jpg', 'http://50states.s3.amazonaws.com/181_2_200c.jpg', '', '1024', '768', 1, 63, '2011-03-31 20:09:28'),
(182, 2, '70', 'The Future', 'Epcot is an odd mix of Futuristic 60''s architecture and topiary trees of elephants.', 'http://50states.s3.amazonaws.com/182_2_1024.jpg', 'http://50states.s3.amazonaws.com/182_2_200c.jpg', '', '1024', '1001', 1, 54, '2011-03-31 20:17:33'),
(183, 2, '70', 'Buzz and Lotso', 'Epcot is in the middle of their annual flower show, and so there''s lots of Pixar topiary. Lotso scared a toddler who spotted him from a distance.', 'http://50states.s3.amazonaws.com/183_2_1024.jpg', 'http://50states.s3.amazonaws.com/183_2_200c.jpg', '', '1024', '1365', 1, 53, '2011-03-31 20:26:42'),
(184, 2, '71', 'Gemini Phone', 'At Kennedy Space Center in Florida.', 'http://50states.s3.amazonaws.com/184_2_1024.jpg', 'http://50states.s3.amazonaws.com/184_2_200c.jpg', '', '1024', '1001', 1, 49, '2011-03-31 20:44:05'),
(185, 2, '71', 'Gemini Capsule', 'The marks are from re-entry into the atmosphere.', 'http://50states.s3.amazonaws.com/185_2_1024.jpg', 'http://50states.s3.amazonaws.com/185_2_200c.jpg', '', '1024', '1001', 1, 58, '2011-03-31 20:49:17'),
(186, 2, '71', 'Gemini', 'I''m glad there are people crazy enough to climb into a tiny tin can and get shot into space on a missile, because I sure don''t want to do it. ', 'http://50states.s3.amazonaws.com/186_2_1024.jpg', 'http://50states.s3.amazonaws.com/186_2_200c.jpg', '', '1024', '768', 1, 81, '2011-03-31 20:53:59'),
(187, 2, '72', 'Live oak caterpillars', 'We went to Blue Springs in Florida and the entire place was crawling, literally, with these funny looking caterpillars.', 'http://50states.s3.amazonaws.com/187_2_1024.jpg', 'http://50states.s3.amazonaws.com/187_2_200c.jpg', '', '1024', '768', 1, 67, '2011-03-31 21:03:08');
INSERT INTO `photos` (`id`, `user_id`, `place_id`, `title`, `caption`, `url`, `thumbnail`, `med`, `width`, `height`, `active`, `views`, `created`) VALUES
(188, 1, '23', 'Moon Tower', 'The Moontowers provided huge amounts of light for the city of Austin. This shows the hand cranked "elevator" that was used to go up and service the bulbs.', 'http://50states.s3.amazonaws.com/188_1_1024.jpg', 'http://50states.s3.amazonaws.com/188_1_200c.jpg', '', '1024', '1365', 1, 68, '2011-04-04 18:50:17'),
(189, 1, '23', 'Moon Tower', 'One of the Austin Moon Towers. This one is about a block or so from the capitol building.', 'http://50states.s3.amazonaws.com/189_1_1024.jpg', 'http://50states.s3.amazonaws.com/189_1_200c.jpg', 'http://50states.s3.amazonaws.com/189_1_600.jpg', '1024', '768', 1, 161, '2011-04-04 18:56:39'),
(190, 1, '24', 'Cliff Dwellings Map', 'A Park Service map showing the layout of the dwellings.', 'http://50states.s3.amazonaws.com/190_1_1024.jpg', 'http://50states.s3.amazonaws.com/190_1_200c.jpg', '', '900', '354', 1, 63, '2011-04-06 19:47:54'),
(191, 1, '25', 'Beginning of the Catwalk Trail', 'This is what you see at first. Not much indication of what is to come other than some pretty nature.', 'http://50states.s3.amazonaws.com/191_1_1024.jpg', 'http://50states.s3.amazonaws.com/191_1_200c.jpg', '', '1024', '683', 1, 42, '2011-04-11 08:35:43'),
(192, 1, '25', 'First Catwalk', 'This is where the catwalks begin. This would be the hardest part of the canyon to get through without the walks as it is very narrow and usually pretty full of rushing water/', 'http://50states.s3.amazonaws.com/192_1_1024.jpg', 'http://50states.s3.amazonaws.com/192_1_200c.jpg', '', '1024', '683', 1, 49, '2011-04-11 08:37:28'),
(193, 1, '25', 'Catwalk Trail Canyon', 'This is looking back on the first canyon.', 'http://50states.s3.amazonaws.com/193_1_1024.jpg', 'http://50states.s3.amazonaws.com/193_1_200c.jpg', '', '1024', '683', 1, 41, '2011-04-11 08:42:31'),
(194, 1, '25', 'Catwalk Trail Canyon', 'Looking back across one of the catwalks that cling to the side of the cliff face.', 'http://50states.s3.amazonaws.com/194_1_1024.jpg', 'http://50states.s3.amazonaws.com/194_1_200c.jpg', 'http://50states.s3.amazonaws.com/194_1_600.jpg', '1024', '683', 1, 55, '2011-04-11 08:44:07'),
(195, 1, '25', 'The Suspension Bridge', 'This is the bridge towards the end of the trail that spans one of the canyons. It looks kinda rickety but i couldn''t get it to break by jumping  up and down on it.', 'http://50states.s3.amazonaws.com/195_1_1024.jpg', 'http://50states.s3.amazonaws.com/195_1_200c.jpg', '', '1024', '683', 1, 54, '2011-04-11 08:48:36'),
(196, 1, '25', 'End of the Trail', 'This is about 1 1/4 miles in. It ends in a little cave that overlooks a big messy waterfall.', 'http://50states.s3.amazonaws.com/196_1_1024.jpg', 'http://50states.s3.amazonaws.com/196_1_200c.jpg', '', '1024', '683', 1, 55, '2011-04-11 08:50:02'),
(197, 1, '25', 'Return Catwalk', 'This is one of the catwalks that heads back to the parking lot.', 'http://50states.s3.amazonaws.com/197_1_1024.jpg', 'http://50states.s3.amazonaws.com/197_1_200c.jpg', '', '1024', '683', 1, 46, '2011-04-11 08:52:05'),
(198, 1, '38', 'Mogollon General store', 'Its a bit of a drive up there, but it''s pretty incredible.', 'http://50states.s3.amazonaws.com/198_1_1024.jpg', 'http://50states.s3.amazonaws.com/198_1_200c.jpg', '', '1024', '683', 1, 46, '2011-04-11 10:31:11'),
(199, 1, '38', 'Mogollon Main Street', 'Looking back towards the the start of town. It was extremely cold up here this day.', 'http://50states.s3.amazonaws.com/199_1_1024.jpg', 'http://50states.s3.amazonaws.com/199_1_200c.jpg', '', '1024', '683', 1, 58, '2011-04-11 10:46:17'),
(200, 1, '38', 'Downtown Mogollon', 'The "Downtown" area. a stretch of old buildings.', 'http://50states.s3.amazonaws.com/200_1_1024.jpg', 'http://50states.s3.amazonaws.com/200_1_200c.jpg', '', '1024', '683', 1, 50, '2011-04-11 10:52:29'),
(201, 1, '38', 'Mountain Door', 'Mogollon has several doors like this leading into the mountainside. Not sure if it from mining, or just a good place for people to store things. There wasn''t anyone around to ask.', 'http://50states.s3.amazonaws.com/201_1_1024.jpg', 'http://50states.s3.amazonaws.com/201_1_200c.jpg', '', '1024', '683', 1, 61, '2011-04-11 10:55:10'),
(202, 1, '28', 'Toilet Rock', 'The GMC in the background of a rock shaped like a toilet at City of Rocks park', 'http://50states.s3.amazonaws.com/202_1_1024.jpg', 'http://50states.s3.amazonaws.com/202_1_200c.jpg', '', '1024', '683', 1, 56, '2011-04-11 11:37:06'),
(203, 1, '28', 'City of Rocks', 'An overview of the "city" which is like a giant decided to create a model of a city with the boulders he found lying around.', 'http://50states.s3.amazonaws.com/203_1_1024.jpg', 'http://50states.s3.amazonaws.com/203_1_200c.jpg', '', '1024', '683', 1, 58, '2011-04-11 11:39:22'),
(205, 1, '28', 'Picnic Rocks', 'There are tons of awesome little picnic spots scattered around in secluded places amongst the rocks.', 'http://50states.s3.amazonaws.com/205_1_1024.jpg', 'http://50states.s3.amazonaws.com/205_1_200c.jpg', '', '1024', '683', 1, 41, '2011-04-11 12:15:24'),
(206, 1, '28', 'Edge of the CIty', 'City of Rocks State Park. It just kinda tapers off on the edges and goes back to being sort of hilly grasslands.', 'http://50states.s3.amazonaws.com/206_1_1024.jpg', 'http://50states.s3.amazonaws.com/206_1_200c.jpg', 'http://50states.s3.amazonaws.com/206_1_600.jpg', '1024', '683', 1, 31, '2011-04-11 12:18:46'),
(207, 1, '26', 'Space Murals Museum', 'This awesomely weird consists of a water tank with murals commemorating american space flight and a bunch of astronaut ephemera.', 'http://50states.s3.amazonaws.com/207_1_1024.jpg', 'http://50states.s3.amazonaws.com/207_1_200c.jpg', 'http://50states.s3.amazonaws.com/207_1_600.jpg', '1024', '683', 1, 43, '2011-04-11 12:22:39'),
(208, 1, '26', 'Random Astroiana', 'Space Murals Museum is full of the most random stuff that seemingly wouldn''t fit in other space museums.', 'http://50states.s3.amazonaws.com/208_1_1024.jpg', 'http://50states.s3.amazonaws.com/208_1_200c.jpg', '', '1024', '683', 1, 61, '2011-04-11 12:34:11'),
(209, 1, '26', 'Space Murals Museum', 'Everything here is just kinda awesomely cluttered and random. Legos, patches, commeorative astronaut trading cards, even displays on tables with lacy doileys.', 'http://50states.s3.amazonaws.com/209_1_1024.jpg', 'http://50states.s3.amazonaws.com/209_1_200c.jpg', '', '1024', '683', 1, 48, '2011-04-11 12:35:57'),
(210, 1, '48', 'Missle Garden', 'The Missile Garden outside the museum at white sands missile range', 'http://50states.s3.amazonaws.com/210_1_1024.jpg', 'http://50states.s3.amazonaws.com/210_1_200c.jpg', '', '1024', '683', 1, 51, '2011-04-18 18:20:57'),
(211, 1, '48', 'Fat Man', 'A replica of the fat man atomic bomb at white sands missile range', 'http://50states.s3.amazonaws.com/211_1_1024.jpg', 'http://50states.s3.amazonaws.com/211_1_200c.jpg', '', '1024', '683', 1, 32, '2011-04-18 18:23:58'),
(212, 1, '48', 'Flying Saucer', 'The Flying Saucer prototype. Possibly built just to cover actual alien activity but more likely just built by some nerdy rocket scientist.', 'http://50states.s3.amazonaws.com/212_1_1024.jpg', 'http://50states.s3.amazonaws.com/212_1_200c.jpg', '', '1024', '683', 1, 87, '2011-04-18 18:25:39'),
(213, 1, '48', 'Micro Missile', 'There are lots of little guys like this at the missile garden in white sands', 'http://50states.s3.amazonaws.com/213_1_1024.jpg', 'http://50states.s3.amazonaws.com/213_1_200c.jpg', '', '1024', '683', 1, 48, '2011-04-18 18:26:49'),
(214, 1, '27', 'White Sands National Monument', 'A lone yucca at sunset.', 'http://50states.s3.amazonaws.com/214_1_1024.jpg', 'http://50states.s3.amazonaws.com/214_1_200c.jpg', '', '1024', '683', 1, 44, '2011-04-18 18:29:11'),
(215, 1, '27', 'The GMC and Shuttlecraft', 'Hanging out together at White Sands National Monument.', 'http://50states.s3.amazonaws.com/215_1_1024.jpg', 'http://50states.s3.amazonaws.com/215_1_200c.jpg', '', '1024', '683', 1, 112, '2011-04-18 18:31:21'),
