(285, 'Elmwood Cemetery', '', '824 S Dudley St', 'Memphis', 'TN', '38106', '', '35.1218058', '-90.02917919999999', 0, 0, 25, '2011-09-12 00:00:00', '2011-09-12 21:22:24'),
(286, 'Memphis Pyramid', '', '1 Auction Ave', 'Memphis', 'TN', '38103', '', '35.155873', '-90.05285800000001', 0, 0, 17, '2011-09-12 00:00:00', '2011-09-12 21:34:38'),
(287, 'Southern Soul BBQ', 'This was one of the best BBQ places we visited on the trip. Like many good BBQ places, it is in a former gas station and when we pulled up they were blasting Steely Dan, which may have predetermined that we would love this place. Their pulled pork was exquisite and the ribs were solid. They also did a great job with having a ton of great regional sauces. ', '2020 Demere Road', 'St. Simons', 'GA', '31522', 'http://www.southernsoulbbq.com', '31.159532', '-81.38819590000003', 0, 0, 0, '2011-04-03 00:00:00', '0000-00-00 00:00:00'),
(288, 'Brown Sugar Kitchen', 'This is one of the best places in the bay area to get southern food. An excellent brunch place, try the chicken and waffles.', '2534 Mandela Pkwy', 'Oakland', 'CA', '94607', 'http://brownsugarkitchen.com/', '37.82026527451321', '-122.28902385029296', 0, 0, 0, '2012-06-22 00:00:00', '0000-00-00 00:00:00');
