INSERT INTO `users` (`id`, `first_name`, `last_name`, `username`, `password`, `email`, `image`, `bio`, `created`) VALUES
(1, 'Paul', 'Cloutier', 'theorem', '', '', 'http://50statesorless.com/img/paul_avatar_small.jpg', 'Paul loves to drive and spends more time looking for the worlds largest X than he probably should. He''s pretty excited about Kentucky bourbon tours and finally seeing New England.', '2011-03-11 20:37:00'),
(2, 'Alana', 'Cloutier', 'kittyholmes', '', '', 'http://50statesorless.com/img/alana_avatar_small.jpg', 'Alana mostly spends her time taking pictures of squirrels and hiding the dog when we go places. She''s pretty excited about seeing as many donut shops as possible.', '2011-03-11 20:38:13');
